INSERT INTO products (id, slug, name, category, hsn_code, short_description, image, origin, sort_order, payload_json, updated_at) VALUES
('whole-red-chili', 'whole-red-chili', 'Whole Red Chillies', 'Whole Spices', '', 'Sun-dried export chillies with calibrated SHU heat, high ASTA color, and stemless options.', '/uploads/upload_1791352991148_duq4y.jpg', 'Guntur, Khammam, Warangal — Andhra Pradesh & Telangana', 0, '{"id":"whole-red-chili","slug":"whole-red-chili","name":"Whole Red Chillies","botanicalName":"Capsicum annuum","scientific":"Capsicum annuum","category":"Whole Spices","categoryKey":"whole-spices","tagline":"Sun-dried export chillies with calibrated SHU heat, high ASTA color, and stemless options.","isFlagship":true,"partUsed":"Sun-dried fruit (pod)","shortDescription":"Sun-dried export chillies with calibrated SHU heat, high ASTA color, and stemless options.","fullDescription":"Origin Exim''s whole red chillies are sourced direct from contracted farmers across the Guntur, Khammam and Warangal belts — the largest contiguous chilli growing region in Asia. Each lot is sun-dried on raised platforms, hand-graded for colour and length, and held in cold storage to preserve volatile oil and natural pigment. Buyers can specify Teja S17 for high pungency, Sannam S4 for balanced colour and heat, 334 for export-grade thickness, or Byadgi for deep red colour with low heat. Stems-on, stemless, and crushed forms are available, and steam-sterilised material is supplied for buyers requiring EU and US FDA microbial compliance.","origin":"Guntur, Khammam, Warangal — Andhra Pradesh & Telangana","grade":"Teja S17 · Sannam S4 · 334 · Wonder Hot · Byadgi","availableForms":["Whole Sun-dried fruit (pod)","Ground Powder"],"packagingOptions":["25kg / 50kg Multi-Wall Kraft Paper Sacks with PE Inner Liner","High-Density Polypropylene (PP) Woven Export Sacks","Custom Private Label Foodservice Pouches Available"],"applications":["Industrial oleoresin extraction","Curry pastes & sauce manufacturing","Snack & seasoning industry","Pharmaceutical capsaicin derivatives","Restaurant & retail culinary use"],"loadability":"≈ 13 – 14 MT per 20ft FCL · 24 – 26 MT per 40ft FCL with stem · stemless approx 10% higher density.","image":"/uploads/upload_1791352991148_duq4y.jpg","specifications":[{"label":"Origin","value":"Guntur, Khammam, Warangal — Andhra Pradesh & Telangana"},{"label":"Botanical Name","value":"Capsicum annuum"},{"label":"Part Used","value":"Sun-dried fruit (pod)"},{"label":"Grade / Varieties","value":"Teja S17 · Sannam S4 · 334 · Wonder Hot · Byadgi"},{"label":"ASTA Colour","value":"60 – 165 ASTA colour units (grade dependent)"},{"label":"Capsaicin / SHU Heat","value":"8,000 – 1,00,000 SHU (grade dependent)"},{"label":"Container Loadability","value":"≈ 13 – 14 MT per 20ft FCL · 24 – 26 MT per 40ft FCL with stem · stemless approx 10% higher density."}],"qualityProcess":["Multi-stage magnetic separation and pneumatic air-sifting to remove field extraneous matter","Optical color Sortex sorting for uniform seed/pod size, color, and density grading","Certified laboratory testing for pesticide MRLs, microbial limits, and heavy metals","Batch-wise moisture-controlled sealed packaging preventing mold and volatile oil oxidation"],"exportInfo":{"minimumOrderQuantity":"1 x 20ft FCL (Mixed container options available for LCL/trial lots)","packagingStandard":"Food-Grade 25kg / 50kg export seaworthy seaworthy bags with inner liner","containerCapacity":"≈ 13 – 14 MT per 20ft FCL · 24 – 26 MT per 40ft FCL with stem · stemle","sampleAvailability":"Complimentary commercial samples dispatched via DHL/FedEx upon request","leadTime":"10 to 14 business days from contract confirmation to Indian port loading","incoterms":"FOB (Mundra, Nhava Sheva, Cochin), CFR, CIF Destination Port"},"faqs":[{"question":"What quality certifications are supplied with Whole Red Chillies shipments?","answer":"Every commercial consignment is accompanied by Phytosanitary Certificate, Certificate of Origin, Commercial Invoice, Packing List, and certified third-party laboratory analysis (SGS / Eurofins upon buyer request) verifying pesticide MRLs and physical purity."},{"question":"Can you customize the packaging and mesh size for Whole Red Chillies?","answer":"Yes, we provide customizable packaging from 25kg multi-wall paper bags with barrier liners to bulk jumbo bags and private label retail pouch packaging. For ground products, mesh size and grind specification can be calibrated precisely to your processing line."}]}'::jsonb, '2026-10-13T07:03:16.271Z'),
('green-cardamom', 'green-cardamom', 'Green Cardamom', 'Whole Spices', '', 'High-altitude Western Ghats bold green pods (6.5mm–8mm) with high essential oil content.', '/uploads/upload_1791352615644_0s75e.jpg', 'Idukki, Kerala & Western Ghats', 1, '{"id":"green-cardamom","slug":"green-cardamom","name":"Green Cardamom","botanicalName":"Elettaria cardamomum","scientific":"Elettaria cardamomum","category":"Whole Spices","categoryKey":"whole-spices","tagline":"High-altitude Western Ghats bold green pods (6.5mm–8mm) with high essential oil content.","isFlagship":true,"partUsed":"Dried whole pod","shortDescription":"High-altitude Western Ghats bold green pods (6.5mm–8mm) with high essential oil content.","fullDescription":"Our Indian green cardamom is harvested from the high-elevation plantations of the Western Ghats, where cool nights concentrate the essential oils that buyers in the Gulf and Europe pay a premium for. Pods are dried under controlled heat to retain the bright green husk, then graded by mechanical sieve into 6.5mm, 7mm, 7.5mm and 8mm bold counts. Origin Exim supplies hand-picked, single-origin lots with documented volatile oil content and zero pesticide residue beyond destination MRLs.","origin":"Idukki, Kerala & Western Ghats","grade":"6.5mm · 7mm · 7.5mm · 8mm bold green","availableForms":["Whole Dried whole pod","Ground Powder"],"packagingOptions":["25kg / 50kg Multi-Wall Kraft Paper Sacks with PE Inner Liner","High-Density Polypropylene (PP) Woven Export Sacks","Custom Private Label Foodservice Pouches Available"],"applications":["Confectionery & bakery","Beverage & coffee blends","Ayurvedic and pharmaceutical formulations","Premium Middle-East culinary use"],"loadability":"≈ 10 MT per 20ft FCL · 18 MT per 40ft FCL.","image":"/uploads/upload_1791352615644_0s75e.jpg","specifications":[{"label":"Origin","value":"Idukki, Kerala & Western Ghats"},{"label":"Botanical Name","value":"Elettaria cardamomum"},{"label":"Part Used","value":"Dried whole pod"},{"labe