('black-pepper', 'black-pepper', 'Black Pepper', 'Whole Spices', '', 'Malabar & Tellicherry garbled black pepper with high piperine content and high bulk density.', '/uploads/upload_1791353086132_trtnu.jpg', 'Malabar coast, Kerala & Karnataka', 2, '{"id":"black-pepper","slug":"black-pepper","name":"Black Pepper","botanicalName":"Piper nigrum","scientific":"Piper nigrum","category":"Whole Spices","categoryKey":"whole-spices","tagline":"Malabar & Tellicherry garbled black pepper with high piperine content and high bulk density.","isFlagship":true,"partUsed":"Sun-dried mature berry","shortDescription":"Malabar & Tellicherry garbled black pepper with high piperine content and high bulk density.","fullDescription":"Origin Exim''s black pepper comes from smallholder estates along India''s Malabar coast — the original home of the spice trade. Berries are vine-ripened, sun-dried on coir mats, and machine-cleaned before mechanical grading by bulk density. We supply 500 GL and 550 GL specifications, hand-picked TGSEB (Tellicherry Garbled Special Extra Bold), and steam-sterilised material for ready-to-use industrial customers.","origin":"Malabar coast, Kerala & Karnataka","grade":"MG1 · 550 GL · 500 GL · TGSEB · Garbled / Ungarbled","availableForms":["Whole Sun-dried mature berry","Ground Powder"],"packagingOptions":["25kg / 50kg Multi-Wall Kraft Paper Sacks with PE Inner Liner","High-Density Polypropylene (PP) Woven Export Sacks","Custom Private Label Foodservice Pouches Available"],"applications":["Meat & seafood processing","Seasoning blends","Pharmaceutical piperine extraction","Retail grinder packs"],"loadability":"Approx. 12-14 MT per 20ft FCL / 24-26 MT per 40ft FCL","image":"/uploads/upload_1791353086132_trtnu.jpg","specifications":[{"label":"Origin","value":"Malabar coast, Kerala & Karnataka"},{"label":"Botanical Name","value":"Piper nigrum"},{"label":"Part Used","value":"Sun-dried mature berry"},{"label":"Grade / Varieties","value":"MG1 · 550 GL · 500 GL · TGSEB · Garbled / Ungarbled"},{"label":"Volatile Oil (VO)","value":"Piperine 4 – 6%"}],"qualityProcess":["Multi-stage magnetic separation and pneumatic air-sifting to remove field extraneous matter","Optical color Sortex sorting for uniform seed/pod size, color, and density grading","Certified laboratory testing for pesticide MRLs, microbial limits, and heavy metals","Batch-wise moisture-controlled sealed packaging preventing mold and volatile oil oxidation"],"exportInfo":{"minimumOrderQuantity":"1 x 20ft FCL (Mixed container options available for LCL/trial lots)","packagingStandard":"Food-Grade 25kg / 50kg export seaworthy seaworthy bags with inner liner","containerCapacity":"≈ 12-14 MT (20ft FCL) / 24-26 MT (40ft FCL)","sampleAvailability":"Complimentary commercial samples dispatched via DHL/FedEx upon request","leadTime":"10 to 14 business days from contract confirmation to Indian port loading","incoterms":"FOB (Mundra, Nhava Sheva, Cochin), CFR, CIF Destination Port"},"faqs":[{"question":"What quality certifications are supplied with Black Pepper shipments?","answer":"Every commercial consignment is accompanied by Phytosanitary Certificate, Certificate of Origin, Commercial Invoice, Packing List, and certified third-party laboratory analysis (SGS / Eurofins upon buyer request) verifying pesticide MRLs and physical purity."},{"question":"Can you customize the packaging and mesh size for Black Pepper?","answer":"Yes, we provide customizable packaging from 25kg multi-wall paper bags with barrier liners to bulk jumbo bags and private label retail pouch packaging. For ground products, mesh size and grind specification can be calibrated precisely to your processing line."}]}'::jsonb, '2026-10-13T07:00:01.932Z'),
('cinnamon', 'cinnamon', 'Cinnamon', 'Whole Spices', '', 'Estate-sourced true Ceylon and cassia quills, machine-graded for essential cinnamaldehyde.', '/assets/products/cinnamon.jpg', 'Kerala & sourced Cassia from Indonesia for blending lots', 3, '{"id":"cinnamon","slug":"cinnamon","name":"Cinnamon","botanicalName":"Cinnamomum verum / cassia","scientific":"Cinnamomum verum / cassia","category":"Whole Spices","categoryKey":"whole-spices","tagline":"Estate-sourced true Ceylon and cassia quills, machine-graded for essential cinnamaldehyde.","isFlagship":false,"partUsed":"Dried inner bark","shortDescription":"Estate-sourced true Ceylon and cassia quills, machine-graded for essential cinnamaldehyde.","fullDescription":"Cinnamon is supplied as long, tightly rolled quills (true Ceylon cinnamomum verum) and as cassia broken / split for industrial buyers. Bark is harvested in the monsoon shoulder season when peeling is cleanest, then sun-cured in shaded yards. Origin Exim grades by quill length and oil content and tests every lot for coumarin where destination markets impose limits.","origin":"Kerala & sourced Cassia from Indonesia for blending lots","grade":"Quills · Broken · Split · Powder","availableForms":["Whole Dried inner bark","Ground Powder"],"packagingOptions":["25kg / 50kg Multi-Wall Kraft Paper Sacks with PE Inner Liner","High-Density Polypropylene (PP) Woven Export Sacks","Custom Private Label Foodservice Pouches Available"],"applications":["Bakery & confectionery","Beverage syrups & infusions","Nutraceutical capsules","Mulled wine and seasonal blends"],"loadability":"Approx. 12-14 MT per 20ft FCL / 24-26 MT per 40ft FCL","image":"/assets/products/cinnamon.jpg","specifications":[{"label":"Origin","value":"Kerala & sourced Cassia from Indonesia for blending lots"},{"label":"Botanical Name","value":"Cinnamomum verum / cassia"},{"label":"Part Used","value":"Dried inner bark"},{"label":"Grade / Varieties","value":"Quills · Broken · Split · Powder"},{"label":"Volatile Oil (VO)","value":"Volatile oil 1.5 – 3%"}],"qualityProcess":["Multi-stage magnetic separation and pneumatic air-sifting to remove field extraneous matter","Optical color Sortex sorting for uniform seed/pod size, color, and density grading","Certified laboratory testing for pesticide MRLs, microbial limits, and heavy metals","Batch-wise moisture-controlled sealed packaging preventing mold and volatile oil oxidation"],"exportInfo":{"minimumOrderQuantity":"1 x 20ft FCL (Mixed container options available for LCL/trial lots)","packagingStandard":"Food-Grade 25kg / 50kg export seaworthy seaworthy bags with inner liner","containerCapacity":"≈ 12-14 MT (20ft FCL) / 24-26 MT (40ft FCL)","sampleAvailability":"Complimentary commercial samples dispatched via DHL/FedEx upon request","leadTime":"10 to 14 business days from contract confirmation to Indian port loading","incoterms":"FOB (Mundra, Nhava Sheva, Cochin), CFR, CIF Destination Port"},"faqs":[{"question":"What quality certifications are supplied with Cinnamon shipments?","answer":"Every commercial consignment is accompanied by Phytosanitary Certificate, Certificate of Origin, Commercial Invoice, Packing List, and certified third-party laboratory analysis (SGS / Eurofins upon buyer request) verifying pesticide MRLs and physical purity."},{"question":"Can you customize the packaging and mesh size for Cinnamon?","answer":"Yes, we provide customizable packaging from 25kg multi-wall paper bags with barrier liners to bulk jumbo bags and private label retail pouch packaging. For ground products, mesh size and grind specification can be calibrated precisely to your processing line."}]}'::jsonb, '2026-10-13T07:00:01.932Z'),
('star-anise', 'star-anise', 'Star Anise', 'Whole Spices', '', 'Intact eight-point stars with verified anethole volatile oil and low broken fraction.', '/assets/products/star-anise.jpg', 'Sourced & cleaned in India for export', 4, '{"id":"star-anise","slug":"star-anise","name":"Star Anise","botanicalName":"Illicium verum","scientific":"Illicium verum","category":"Whole Spices","categoryKey":"whole-spices","tagline":"Intact eight-point stars with verified anethole volatile oil and low broken fraction.","isFlagship":false,"partUsed":"Dried fruit (whole star)","shortDescription":"Intact eight-point stars with verified anethole volatile oil and low broken fraction.","fullDescription":"Origin Exim supplies cleaned, sorted star anise with full eight-point stars, low broken percentage and verified anethole content. Lots are sieved, manually picked for foreign matter and tested for shikimic acid yield where requested by pharmaceutical buyers.","origin":"Sourced & cleaned in India for export","grade":"Whole star · Broken · Powder","availableForms":["Whole Dried fruit (whole star)","Ground Powder"],"packagingOptions":["25kg / 50kg Multi-Wall Kraft Paper Sacks with PE Inner Liner","High-Density Polypropylene (PP) Woven Export Sacks","Custom Private Label Foodservice Pouches Available"],"applications":["Five-spice & Asian seasoning blends","Liqueur & beverage flavouring","Pharmaceutical (shikimic acid precursor)"],"loadability":"Approx. 12-14 MT per 20ft FCL / 24-26 MT per 40ft FCL","image":"/assets/products/star-anise.jpg","specifications":[{"label":"Origin","value":"Sourced & cleaned in India for export"},{"label":"Botanical Name","value":"Illicium verum"},{"label":"Part Used","value":"Dried fruit (whole star)"},{"label":"Grade / Varieties","value":"Whole star · Broken · Powder"},{"label":"Volatile Oil (VO)","value":"Anethole ≥ 85% in essential oil fraction"}],"qualityProcess":["Multi-stage magnetic separation and pneumatic air-sifting to remove field extraneous matter","Optical color Sortex sorting for uniform seed/pod size, color, and density grading","Certified laboratory testing for pesticide MRLs, microbial limits, and heavy metals","Batch-wise moisture-controlled sealed packaging preventing mold and volatile oil oxidation"],"exportInfo":{"minimumOrderQuantity":"1 x 20ft FCL (Mixed container options available for LCL/trial lots)","packagingStandard":"Food-Grade 25kg / 50kg export seaworthy seaworthy bags with inner liner","containerCapacity":"≈ 12-14 MT (20ft FCL) / 24-26 MT (40ft FCL)","sampleAvailability":"Complimentary commercial samples dispatched via DHL/FedEx upon request","leadTime":"10 to 14 business days from contract confirmation to Indian port loading","incoterms":"FOB (Mundra, Nhava Sheva, Cochin), CFR, CIF Destination Port"},"faqs":[{"question":"What quality certifications are supplied with Star Anise shipments?","answer":"Every commercial consignment is accompanied by Phytosanitary Certificate, Certificate of Origin, Commercial Invoice, Packing List, and certified third-party laboratory analysis (SGS / Eurofins upon buyer request) verifying pesticide MRLs and physical purity."},{"question":"Can you customize the packaging and mesh size for Star Anise?","answer":"Yes, we provide customizable packaging from 25kg multi-wall paper bags with barrier liners to bulk jumbo bags and private label retail pouch packaging. For ground products, mesh size and grind specification can be calibrated precisely to your processing line."}]}'::jsonb, '2026-10-13T07:00:01.932Z'),
('clove', 'clove', 'Cloves', 'Whole Spices', '', 'Hand-picked whole dried cloves with intact flower heads and rich natural eugenol oil.', '/assets/products/clove.jpg', 'Nilgiris & Kerala', 5, '{"id":"clove","slug":"clove","name":"Cloves","botanicalName":"Syzygium aromaticum","scientific":"Syzygium aromaticum","category":"Whole Spices","categoryKey":"whole-spices","tagline":"Hand-picked whole dried cloves with intact flower heads and rich natural eugenol oil.","isFlagship":false,"partUsed":"Dried unopened flower bud","shortDescription":"Hand-picked whole dried cloves with intact flower heads and rich natural eugenol oil.","fullDescription":"Cloves are harvested by hand at the unopened bud stage, sun-dried until they turn the characteristic deep brown, then hand-sorted to remove khoker (head-less) and stem fractions. Origin Exim supplies premium hand-picked stemless lots and bulk machine-cleaned grades with documented eugenol content for pharmaceutical and food-industry buyers.","origin":"Nilgiris & Kerala","grade":"Hand-picked · Machine-cleaned · Stemless · With stem","availableForms":["Whole Dried unopened flower bud","Ground Powder"],"packagingOptions":["25kg / 50kg Multi-Wall Kraft Paper Sacks with PE Inner Liner","High-Density Polypropylene (PP) Woven Export Sacks","Custom Private Label Foodservice Pouches Available"],"applications":["Meat curing & processed food","Dental & pharmaceutical formulations","Tobacco and incense industries","Premium culinary use"],"loadability":"Approx. 12-14 MT per 20ft FCL / 24-26 MT per 40ft FCL","image":"/assets/products/clove.jpg","specifications":[{"label":"Origin","value":"Nilgiris & Kerala"},{"label":"Botanical Name","value":"Syzygium aromaticum"},{"label":"Part Used","value":"Dried unopened flower bud"},{"label":"Grade / Varieties","value":"Hand-picked · Machine-cleaned · Stemless · With stem"},{"label":"Volatile Oil (VO)","value":"Eugenol ≥ 80% in volatile oil"}],"qualityProcess":["Multi-stage magnetic separation and pneumati