-- -------------------------------------------------------------
-- 3. Table: blog_posts
-- -------------------------------------------------------------
DROP TABLE IF EXISTS blog_posts CASCADE;
CREATE TABLE blog_posts (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  category TEXT NOT NULL,
  author TEXT NOT NULL,
  date TEXT NOT NULL,
  featured BOOLEAN NOT NULL DEFAULT false,
  image TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  payload_json JSONB NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_blog_posts_slug ON blog_posts (slug);
ALTER TABLE blog_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow full access for blog_posts" ON blog_posts FOR ALL USING (true) WITH CHECK (true);

INSERT INTO blog_posts (id, slug, title, category, author, date, featured, image, sort_order, payload_json, updated_at) VALUES
('post-1791189419181', 'how-to-import-spices-from-india-a-complete-guide-for-international-buyers', 'How to Import Spices from India: A Complete Guide for International Buyers', 'Export Insights', 'Patel Arsh', 'October 5, 2026', false, '/uploads/upload_1791190313826_tbhz6.jpg', 0, '{"id":"post-1791189419181","slug":"how-to-import-spices-from-india-a-complete-guide-for-international-buyers","title":"How to Import Spices from India: A Complete Guide for International Buyers","category":"Export Insights","date":"October 5, 2026","rawDate":"2026-10-05","readTime":"5 min read","author":"Patel Arsh","authorRole":"Commodity Research Analyst","authorId":"usr-1791183682976","excerpt":"Discover how to import spices from India with this complete guide covering reliable suppliers, product quality, export packaging, documentation, shipping, and key considerations for international buyers.","image":"/uploads/upload_1791190313826_tbhz6.jpg","seoTitle":"How to Import Spices from India: A Complete Guide for International Buyers | Origintra Exim Insights","metaDescription":"","tableOfContents":["Introduction","Key Market Insights","Summary"],"content":[{"heading":"Introduction","paragraphs":["India is one of the world''s leading sources of spices, offering a wide range of whole and processed products for international markets. From red chilli and turmeric to cumin, coriander, and moringa powder, Indian spices are widely sourced by importers, wholesalers, food manufacturers, distributors, and commercial buyers.  ","For international buyers, choosing the right Indian spice exporter is essential for maintaining consistent quality, reliable supply, competitive pricing, and smooth international trade. This guide explains the key factors to consider when sourcing and importing spices from India."]},{"heading":"Key Market Insights","paragraphs":["India offers a diverse range of spices suitable for international sourcing. Popular export products include red chilli, turmeric, cumin, coriander, black pepper, and various processed spice powders.  ","When selecting a supplier, buyers should evaluate product specifications, quality standards, processing practices, packaging options, order quantities, documentation, and the supplier''s ability to maintain consistent supply.  \nExport packaging is particularly important because spices must be protected from moisture, contamination, and damage during transportation. Depending on the product and destination, buyers may request food-grade bags, bulk packaging, vacuum packaging, or customized packaging solutions.  ","International buyers should also confirm the import requirements of their destination country, including applicable food-safety standards, certificates, labeling requirements, and customs documentation."]},{"heading":"How to Import Spices from India","paragraphs":["The spice import process generally begins with identifying the required product, quantity, quality specifications, packaging, and destination market. Buyers can then contact a suitable Indian exporter to discuss product availability and receive a quotation.  ","Once the specifications and commercial terms are agreed upon, the exporter prepares the products according to the buyer''s requirements. Appropriate packaging and export documentation are arranged before the shipment is dispatched through the selected logistics channel.  \nBefore placing an order, international buyers should confirm the product specification, quantity, packaging, required certificates, payment terms, shipping terms, destination port, and expected delivery timeline. Clear communication at every stage helps create a smoother and more reliable sourcing process.","Looking for a reliable Indian spice supplier? Origintra Exim works with international buyers looking to source quality Indian spices for global markets. Contact us to discuss your product requirements, bulk orders, packaging, and export enquiries."]}],"relatedSlugs":[]}'::jsonb, '2026-10-13T07:00:01.932Z'),
('indias-role-in-global-spice-trade', 'indias-role-in-global-spice-trade', 'India’s Role in the Global Spice Trade', 'Global Trade', 'Origintra Commercial Research Desk', 'March 20, 2026', false, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=1200&q=80', 1, '{"id":"indias-role-in-global-spice-trade","slug":"indias-role-in-global-spice-trade","title":"India’s Role in the Global Spice Trade","category":"Global Trade","date":"March 20, 2026","readTime":"6 min read","author":"Origintra Commercial Research Desk","authorRole":"Trade Insights & Global Logistics","excerpt":"An overview of why India remains the preeminent epicenter for international spice production, biodiversity, and commercial export supply chains.","image":"https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=1200&q=80","seoTitle":"India’s Role in the Global Spice Trade | Origintra Exim Insights","metaDescription":"Discover why India continues to dominate global spice production and trade, from diverse agro-climatic zones to modern export infrastructure.","tableOfContents":["Agro-Climatic Diversity & Indigenous Cultivation","The Shift from Raw Trading to Regulated Processing","Quality Compliance and Global Market Integration","Modern Maritime Infrastructure & Direct Shipping","Origintra Exim’s Role in the Value Chain"],"content":[{"heading":"Agro-Climatic Diversity & Indigenous Cultivation","paragraphs":["For centuries, India has occupied a central position in the international movement of spices. Spanning sub-tropical plains, arid plateaus, and rainforest mountain ranges, India’s micro-climates foster agricultural conditions capable of producing a vast array of spices with distinct aroma, heat, and volatile oil profiles.","From the high-elevation slopes of the Western Ghats producing prized cardamom and black pepper to the sun-drenched semi-arid soils of Andhra Pradesh, Gujarat, and Rajasthan cultivating red chilli, cumin, and coriander, the country offers agricultural breadth unmatched by any single origin."]},{"heading":"The Shift from Raw Trading to Regulated Processing","paragraphs":["In recent decades, India’s spice sector has undergone a fundamental transformation. What was historically characterized by localized auction mandis has evolved into a structured export industry powered by modern sortex optical sorting, steam sterilization, cryogenic grinding, and accredited laboratory testing.","International food companies and ingredient manufacturers no longer source solely on appearance. Today’s global buyers demand tight tolerances on moisture levels, microbiological counts, volatile oils, and stringent compliance with pesticide Maximum Residue Limits (MRLs). Indian export infrastructure has modernized rapidly to satisfy these stringent requirements."]},{"heading":"Quality Compliance and Global Market Integration","paragraphs":["Exporting agricultural commodities to demanding markets in North America, Europe, the Middle East, and Asia requires strict adherence to international sanitary and phytosanitary protocols. Standardized documentation—including Certificates of Analysis, Phytosanitary Certificates, Non-GMO declarations, and Certificates of Origin—is now fundamental to smooth port clearance.","Working in alignment with accredited NABL analytical laboratories and internationally recognized inspection authorities like SGS and Bureau Veritas, Indian exporters deliver verified consignments that pass border clearance with consistency."]},{"heading":"Modern Maritime Infrastructure & Direct Shipping","paragraphs":["The logistics foundation supporting Indian exports has expanded with world-class deep-water container terminals. Gateway ports such as Mundra and Pipavav on the western coast and Cochin, Chennai, and Krishnapatnam on the southern coast offer direct container vessel sailings to key hubs including Jebel Ali, Rotterdam, Hamburg, Singapore, and New York/New Jersey.","With advanced container freight stations (CFS), container desiccants, and containerization standards, spices arrive at overseas destination ports with their volatile oils, color, and aroma fully preserved."]},{"heading":"Origintra Exim’s Role in the Value Chain","paragraphs":["At Origintra Exim, our mission is to make international trade predictable, transparent, and quality-driven. We act as a reliable bridge between genuine Indian sourcing networks and discerning global buyers, ensuring that each container dispatched represents dependable supply and verified specifications."]}],"relatedSlugs":["how-international-buyers-source-indian-spices","a-practical-guide-to-importing-spices-from-india"]}'::jsonb, '2026-10-13T07:00:01.932Z'),
('how-international-buyers-source-indian-spices', 'how-international-buyers-source-indian-spices', 'How International Buyers Source Indian Spices', 'Sourcing', 'Patel Arsh', 'March 14, 2026', false, '/assets/about/container-ship-port.jpg', 2, '{"id":"how-international-buyers-source-indian-spices","slug":"how-international-buyers-source-indian-spices","title":"How International Buyers Source Indian Spices","category":"Sourcing","date":"March 14, 2026","readTime":"7 min read","author":"Patel Arsh","authorRole":"Commodity Research Analyst","excerpt":"A comprehensive operational look at best practices for overseas procurement managers sourcing bulk spices and botanicals from India.","image":"/assets/about/container-ship-port.jpg","seoTitle":"How International Buyers Source Indian Spices | Origintra Exim","metaDescription":"Learn the essential criteria international procurement teams evaluate when sourcing bulk Indian spices: grading, moisture, packaging, and incoterms.","tableOfContents":["Defining Clear Technical Specifications","Understanding Harvest Calendars & Price Cycles","Sample Evaluation vs. Commercial FCL Shipments","Packaging Selection & Maritime Transit Durability","Establishing Resilient Commercial Partnerships"],"content":[{"heading":"Defining Clear Technical Specifications","paragraphs":["Successful international spice procurement begins with precise technical clarity. Vague inquiries such as \"need good quality turmeric\" lead to commercial misalignment. Experienced procurement managers specify exact physical and chemical parameters: target botanical grade, maximum moisture percentage, required volatile oil or curcumin content, foreign matter limits, and allowable split or broken seed thresholds.","When technical expectations are defined upfront, exporters can accurately align batch procurement from the appropriate regional mandis and tailor mechanical cleaning accordingly."]},{"heading":"Understanding Harvest Calendars & Price Cycles","paragraphs":["Agricultural commodities follow seasonal harvest cycles that significantly influence availability, physical freshness, and pricing dynamics. For instance, Indian cumin arrives primarily between February and April in Gujarat and Rajasthan, while dry red chilli arrivals peak from January to April in Andhra Pradesh.","Buyers who plan procurement during peak harvest windows benefit from optimal selection, higher volatile oil retention, and favorable market depth. Conversely, off-season purchasing draws on cold-storage stocks, which require verification of color retention and moisture stability."]},{"heading":"Sample Evaluation vs. Commercial FCL Shipments","paragraphs":["Pre-shipment sampling is standard practice in international trade. Reliable suppliers provide factual representative samples taken from active commercial lots rather than selectively hand-picked laboratory specimens.","Overseas buyers evaluate sensory appearance, aroma, moisture, and laboratory parameters upon receiving air-couriered samples. Establishing clear pre-shipment inspection clauses—such as joint sampling at the stuffing CFS or certification by third-party surveyors—protects commercial interests."]},{"heading":"Packaging Selection & Maritime Transit Durability","paragraphs":["Ocean transport across different climate zones introduces humidity variations and temperature fluctuations inside ocean containers. Selecting the right packaging is crucial: multi-layer kraft paper bags with inner polyethylene liners protect seed spices from atmospheric humidity, while vacuum-sealed foil packs preserve dehydrated leaves and powders like moringa.","Deploying container desiccants (calcium chloride hanging bags) and kraft paper floor lining prevents container condensation sweat from damaging cargo during multi-week sea voyages."]},{"heading":"Establishing Resilient Commercial Partnerships","paragraphs":["In global commodity trade, long-term consistency outweighs short-term opportunistic spot buying. International buyers benefit most from partnering with transparent export partners who provide honest market intelligence, timely documentation dispatch, and dependable shipping schedules."]}],"relatedSlugs":["indias-role-in-global-spice-trade","understanding-indian-red-chilli-for-global-markets"],"rawDate":"2026-03-13","authorId":"usr-1791183682966"}'::jsonb, '2026-10-13T07:00:01.932Z'),
('understanding-indian-red-chilli-for-global-markets', 'understanding-indian-red-chilli-for-global-markets', 'Understanding Indian Red Chilli for Global Markets', 'Indian Spices', 'Origintra Quality Desk', 'February 28, 2026', false, 'https://images.unsplash.com/photo-1588252303782-cb80119abd6d?auto=format&fit=crop&w=1200&q=80', 3, '{"id":"understanding-indian-red-chilli-for-global-markets","slug":"understanding-indian-red-chilli-for-global-markets","title":"Understanding Indian Red Chilli for Global Markets","category":"Indian Spices","date":"February 28, 2026","readTime":"5 min read","author":"Origintra Quality Desk","authorRole":"Commodity Evaluation Specialist","excerpt":"Varieties, heat levels, color values (ASTA), and commercial processing options for international food manufacturers and spice grinders.","image":"https://images.unsplash.com/photo-1588252303782-cb80119abd6d?auto=format&fit=crop&w=1200&q=80","seoTitle":"Understanding Indian Red Chilli for Global Markets | Origintra Exim","metaDescription":"A technical guide to Indian dry red chilli varieties including Teja, Sanam, and Byadgi. Learn how Scoville heat and ASTA color values define usage.","tableOfContents":["The Commercial Significance of Indian Chillies","Key Commercial Varieties: Teja, Sanam & Byadgi","Balancing Scoville Heat (SHU) and Color (ASTA)","Processing Forms: Whole, Stemless, Flakes, & Powder","Export Quality Controls & Storage Requirements"],"content":[{"heading":"The Commercial Significance of Indian Chillies","paragraphs":["India is the world’s largest producer and exporter of dried red chillies, cultivating an extraordinary variety of cultivars with heat indices ranging from mild to intensely pungent. For international food processors, hot sauce makers, and spice brand packagers, Indian chillies offer consistent supply and cost efficiency across diverse processing applications."]},{"heading":"Key Commercial Varieties: Teja, Sanam & Byadgi","paragraphs":["Different regional varieties serve distinct industrial requirements: Teja (S17) from Guntur is known for fiery heat (typically 50,000 to 75,000+ SHU) and thin skin, making it the premier choice for spicy sauces, oleoresin extraction, and industrial heat formulations.","S4 Sanam offers a balanced moderate heat (25,000 to 40,000 SHU) with good color depth, serving as a versatile foundation for blended curry powders and table seasonings. Byadgi chilli from Karnataka features a deeply wrinkled pod with mild heat and rich natural red pigmentation (high ASTA color value), prized for creating rich red curries and marinades without overpowering pungency."]},{"heading":"Balancing Scoville Heat (SHU) and Color (ASTA)","paragraphs":["Commercial buyers classify chillies along two primary axes: Scoville Heat Units (SHU, reflecting capsaicin concentration) and the American Spice Trade Association (ASTA) color index. Formulators calculate exact blend ratios to achieve target redness and pungency without resorting to artificial coloring agents."]},{"heading":"Processing Forms: Whole, Stemless, Flakes, & Powder","paragraphs":["Chillies can be exported in several forms: whole with stem (economical for bulk volume), stemless (where the calyx and stem are manually or mechanically excised to lower grinding costs), crushed chilli flakes (standardized with controlled seed ratios for pizza toppings and seasoning rubs), and ground fine powder."]},{"heading":"Export Quality Controls & Storage Requirements","paragraphs":["Preserving red chilli quality requires strict moisture management (kept below 11% to prevent fungal growth and aflatoxin development). Export containers are carefully inspected for cleanliness, deodorization, and proper ventilation to ensure pods arrive crisp, bright, and insect-free."]}],"relatedSlugs":["indias-role-in-global-spice-trade","a-practical-guide-to-importing-spices-from-india"]}'::jsonb, '2026-10-13T07:00:01.932Z'),
('a-practical-guide-to-importing-spices-from-india', 'a-practical-guide-to-importing-spices-from-india', 'A Practical Guide to Importing Spices from India', 'Export Insights', 'Origintra Commercial Documentation Team', 'February 15, 2026', false, 'https://images.unsplash.com/photo-1578575437130-527eed3abbec?auto=format&fit=crop&w=1200&q=80', 4, '{"id":"a-practical-guide-to-importing-spices-from-india","slug":"a-practical-guide-to-importing-spices-from-india","title":"A Practical Guide to Importing Spices from India","category":"Export Insights","date":"February 15, 2026","readTime":"8 min read","author":"Origintra Commercial Documentation Team","authorRole":"Trade Compliance & Customs Operations","excerpt":"Essential documentation, Incoterms, container stuffing, and customs clearance procedures for first-time and seasoned spice importers.","image":"https://images.unsplash.com/photo-1578575437130-527eed3abbec?auto=format&fit=crop&w=1200&q=80","seoTitle":"A Practical Guide to Importing Spices from India | Origintra Exim","metaDescription":"Step-by-step export guide: Incoterms (FOB vs CIF), required customs documents (COO, Phytosanitary, COA), container stuffing, and transit planning.","tableOfContents":["Choosing the Right Incoterm: FOB, CFR, or CIF","The Essential Export Documentation Checklist","Container Stuffing, Weight Limits, and Stowage","Phytosanitary Inspection & Plant Quarantine Protocols","Destination Customs Clearance & Cargo Delivery"],"content":[{"heading":"Choosing the Right Incoterm: FOB, CFR, or CIF","paragraphs":["Selecting the appropriate Incoterm defines commercial responsibilities and risk transfer between exporter and buyer. Under FOB (Free on Board - Indian Port), the buyer arranges and controls ocean freight via their nominated shipping line, which provides greater control over destination terminal handling and free demurrage days.","Under CFR (Cost and Freight) or CIF (Cost, Insurance, and Freight), Origintra Exim manages vessel booking, container trucking, port terminal handling, ocean freight, and comprehensive marine insurance up to the destination discharge port. This provides complete freight cost certainty for the buyer."]},{"heading":"The Essential Export Documentation Checklist","paragraphs":["Smooth customs release depends entirely on accurate, harmonized documentation. Standard documentation dispatched with each commercial shipment includes:","1. Commercial Invoice & Detailed Packing List (itemizing gross/net weight and container seal numbers)","2. Clean On-Board Ocean Bill of Lading (Originals or Express Telex Release)","3. Certificate of Origin (issued by authorized Chambers of Commerce or Government authorities)","4. Phytosanitary Certificate (issued by Ministry of Agriculture Plant Quarantine authorities)","5. Certificate of Analysis (COA) detailing physical purity and chemical test parameters","6. Fumigation Certificate (Phosphine / Methyl Bromide as mandated by destination country standards)"]},{"heading":"Container Stuffing, Weight Limits, and Stowage","paragraphs":["Spices possess differing bulk densities. Heavy seed spices such as cumin and turmeric allow a 20ft container to reach 14 to 19 metric tons, whereas light, voluminous crops like whole coriander seeds or dry red chilli reach volumetric cubic limits at 6.5 to 11 metric tons in loose packaging.","Understanding cargo volume allows buyers to choose between standard 20ft dry vans or 40ft High Cube containers to optimize per-ton ocean freight expenditure."]},{"heading":"Phytosanitary Inspection & Plant Quarantine Protocols","paragraphs":["Prior to vessel loading, agricultural cargo is inspected by authorized plant protection officials to certify that the shipment is free from quarantine pests, soil contaminants, and regulated weed seeds. A formal Phytosanitary Certificate is issued and submitted with customs clearance manifests."]},{"heading":"Destination Customs Clearance & Cargo Delivery","paragraphs":["Pre-alert shipping manifests and non-negotiable draft copies of all documents are emailed to the buyer as soon as the vessel departs Indian waters. This enables the buyer’s customs broker to prepare import declarations and arrange port release well before the vessel berths."]}],"relatedSlugs":["how-international-buyers-source-indian-spices","indias-role-in-global-spice-trade"]}'::jsonb, '2026-10-13T07:00:01.932Z');

