INSERT INTO testimonials (id, buyer_name, company, country, flag, product_supplied, container_type, quote, rating, verified, date, created_at, payload_json) VALUES
('t-1', 'Tariq Al-Mansoor', 'Al-Ameen Foodstuff Trading LLC', 'United Arab Emirates', '🌐', 'Guntur S17 Dried Red Chilli', '2 x 20ft FCL (28 MT)', 'We have been ordering Guntur stemless chillies from Origintra for our wholesale distribution in Dubai. Clean lot, moisture was well within our limits, and the container stuffing photos were shared on WhatsApp before dispatch from Mundra. The original documents reached our customs broker before the ship docked at Jebel Ali. Very honest and responsive team to work with.', 5, true, '', '2026-08-15T10:00:00.000Z', '{"id":"t-1","author":"Tariq Al-Mansoor","role":"Procurement Director","company":"Al-Ameen Foodstuff Trading LLC","country":"United Arab Emirates","destinationPort":"Port of Jebel Ali, UAE","commodity":"Guntur S17 Dried Red Chilli","volumeOrType":"2 x 20ft FCL (28 MT)","rating":5,"createdAt":"2026-08-15T10:00:00.000Z","testimonial":"We have been ordering Guntur stemless chillies from Origintra for our wholesale distribution in Dubai. Clean lot, moisture was well within our limits, and the container stuffing photos were shared on WhatsApp before dispatch from Mundra. The original documents reached our customs broker before the ship docked at Jebel Ali. Very honest and responsive team to work with."}'::jsonb),
('t-2', 'Lars van der Meer', 'Nordic Spice & Seasoning Blends B.V.', 'Netherlands', '🌐', 'Salem Turmeric Fingers & Powder', '1 x 20ft FCL (18 MT)', 'Importing turmeric into the EU can be tricky with pesticide residue regulations. Origintra provided certified lab test reports from an accredited lab prior to shipment, and our independent testing at Rotterdam port matched the specs completely. Goods were well palletized with zero bag damage. Smooth coordination from start to finish.', 5, true, '', '2026-08-28T14:30:00.000Z', '{"id":"t-2","author":"Lars van der Meer","role":"Supply Chain Manager","company":"Nordic Spice & Seasoning Blends B.V.","country":"Netherlands","destinationPort":"Port of Rotterdam, Netherlands","commodity":"Salem Turmeric Fingers & Powder","volumeOrType":"1 x 20ft FCL (18 MT)","rating":5,"createdAt":"2026-08-28T14:30:00.000Z","testimonial":"Importing turmeric into the EU can be tricky with pesticide residue regulations. Origintra provided certified lab test reports from an accredited lab prior to shipment, and our independent testing at Rotterdam port matched the specs completely. Goods were well palletized with zero bag damage. Smooth coordination from start to finish."}'::jsonb),
('t-3', 'Mei-Ling Chen', 'Nusantara Food Ingredients Pte Ltd', 'Singapore', '🌐', 'Machine-Cleaned Cumin & Coriander Seeds', 'Quarterly Contract (24 MT)', 'We use Indian cumin and coriander seeds for our seasoning manufacturing line in Jurong. Sourcing from Origintra has been very dependable—high seed purity, strong aroma, and no dust or foreign seeds. Their weekly vessel tracking updates made planning our production schedule simple.', 5, true, '', '2026-09-05T09:15:00.000Z', '{"id":"t-3","author":"Mei-Ling Chen","role":"Senior Sourcing Lead","company":"Nusantara Food Ingredients Pte Ltd","country":"Singapore","destinationPort":"Port of Singapore (PSA)","commodity":"Machine-Cleaned Cumin & Coriander Seeds","volumeOrType":"Quarterly Contract (24 MT)","rating":5,"createdAt":"2026-09-05T09:15:00.000Z","testimonial":"We use Indian cumin and coriander seeds for our seasoning manufacturing line in Jurong. Sourcing from Origintra has been very dependable—high seed purity, strong aroma, and no dust or foreign seeds. Their weekly vessel tracking updates made planning our production schedule simple."}'::jsonb),
('t-4', 'Dr. Klaus Weber', 'Bavarian Seasonings & Botanicals GmbH', 'Germany', '🌐', 'Alleppey Green Cardamom (8mm Bold)', 'LCL Consignment (2.5 MT)', 'We placed an initial commercial order of 8mm Alleppey green cardamom in aroma-sealed foil packaging. The uniform green color, bold size, and essential oil content were consistent across the whole shipment. Everything passed German customs and health inspection without any queries.', 5, true, '', '2026-09-18T16:00:00.000Z', '{"id":"t-4","author":"Dr. Klaus Weber","role":"Head of Raw Materials Purchasing","company":"Bavarian Seasonings & Botanicals GmbH","country":"Germany","destinationPort":"Port of Hamburg, Germany","commodity":"Alleppey Green Cardamom (8mm Bold)","volumeOrType":"LCL Consignment (2.5 MT)","rating":5,"createdAt":"2026-09-18T16:00:00.000Z","testimonial":"We placed an initial commercial order of 8mm Alleppey green cardamom in aroma-sealed foil packaging. The uniform green color, bold size, and essential oil content were consistent across the whole shipment. Everything passed German customs and health inspection without any queries."}'::jsonb),
('t-5', 'Marcus Sterling', 'Commonwealth Seasoning Mills Ltd', 'United Kingdom', '🌐', 'Tellicherry Black Pepper (570 g/L)', '1 x 20ft FCL (16 MT)', 'First time working with Origintra for bulk black pepper. The density and pungency were exactly what we agreed upon during sample approval. The container was well stuffed with silica traps so there was zero condensation during ocean transit. We have already placed our repeat order for next quarter.', 5, true, '', '2026-09-25T11:45:00.000Z', '{"id":"t-5","author":"Marcus Sterling","role":"Import Operations Director","company":"Commonwealth Seasoning Mills Ltd","country":"United Kingdom","destinationPort":"Port of Felixstowe, UK","commodity":"Tellicherry Black Pepper (570 g/L)","volumeOrType":"1 x 20ft FCL (16 MT)","rating":5,"createdAt":"2026-09-25T11:45:00.000Z","testimonial":"First time working with Origintra for bulk black pepper. The density and pungency were exactly what we agreed upon during sample approval. The container was well stuffed with silica traps so there was zero condensation during ocean transit. We have already placed our repeat order for next quarter."}'::jsonb),
('t-6', 'David Rosenfeld', 'Atlantic Spice & Specialty Importers Inc.', 'United States', '🌐', 'Sortex Fennel & Cumin Seeds', 'Mixed 40ft Container (22 MT)', 'Consolidating different seed spices into a single 40ft container saved us substantial ocean freight. Origintra handled the FDA prior notice documentation, phytosanitary certificate, and palletizing professionally. No delays at US customs entry. Straightforward communication and reliable quality.', 5, true, '', '2026-10-02T13:20:00.000Z', '{"id":"t-6","author":"David Rosenfeld","role":"VP Sourcing & Procurement","company":"Atlantic Spice & Specialty Importers Inc.","country":"United States","destinationPort":"Port of New York / NJ, USA","commodity":"Sortex Fennel & Cumin Seeds","volumeOrType":"Mixed 40ft Container (22 MT)","rating":5,"createdAt":"2026-10-02T13:20:00.000Z","testimonial":"Consolidating different seed spices into a single 40ft container saved us substantial ocean freight. Origintra handled the FDA prior notice documentation, phytosanitary certificate, and palletizing professionally. No delays at US customs entry. Straightforward communication and reliable quality."}'::jsonb);

-- -------------------------------------------------------------
-- 9. Table: audit_logs
-- -------------------------------------------------------------
DROP TABLE IF EXISTS audit_logs CASCADE;
CREATE TABLE audit_logs (
  id BIGSERIAL PRIMARY KEY,
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  summary TEXT NOT NULL,
  created_at TEXT NOT NULL
);
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow full access for audit_logs" ON audit_logs FOR ALL USING (true) WITH CHECK (true);
